/**
 * Phase 4A synthetic evaluation. No network and no real NBA data: the league is
 * generated by __fixtures__/evaluationLeague.ts.
 *
 *   npm run nba:synthetic-eval
 *   npm run nba:synthetic-eval -- --seed=7 --out=<file.json>
 *
 * Results are mechanism checks on a league whose effects were written by the
 * models' author. They are not evidence of real-world accuracy, and the
 * manifest says so (evidenceClass "synthetic", realDataEligible false).
 */
import { writeFileSync } from "node:fs";
import { DEFAULT_EVALUATION_LEAGUE, generateEvaluationLeague } from "../src/lib/nba/props/__fixtures__/evaluationLeague";
import { rollingFolds } from "../src/lib/nba/props/evaluation/clock";
import { runEvaluation, type EvaluationReport } from "../src/lib/nba/props/evaluation/runner";
import { CONDITIONAL_METHODS, type FoldSpec } from "../src/lib/nba/props/evaluation/types";
import { DEFAULT_MINUTES_V1_PARAMS } from "../src/lib/nba/props/evaluation/minutesV1Candidate";
import { BASELINE_V0_PUBLIC_PARAMS } from "../src/lib/nba/props/projection";
import { SOURCE_LICENSES } from "../src/lib/nba/props/sources/licenses";

function arg(name: string, fallback: string): string {
  const hit = process.argv.slice(2).find((value) => value.startsWith(`--${name}=`));
  return hit ? hit.slice(name.length + 3) : fallback;
}

const f = (value: number | null | undefined, digits = 3) => (value === null || value === undefined ? "-" : value.toFixed(digits));

function seasonFolds(prefix: string, firstTrainStart: string, lastDate: string): FoldSpec[] {
  return rollingFolds({ firstTrainStart, trainDays: 28, validationDays: 14, stepDays: 14, lastDate }).map((fold) => ({ ...fold, name: `${prefix}-${fold.name}` }));
}

function printConditional(report: EvaluationReport): void {
  const { commonSample } = report.pooled.conditional;
  console.log(`\nConditional on playing (common sample n=${commonSample.n}); error = predicted - actual`);
  for (const stat of ["minutes", "pts", "reb", "ast"] as const) {
    console.log(`  ${stat.toUpperCase()}`);
    console.log("    method            n      MAE   medAE    bias");
    for (const method of CONDITIONAL_METHODS) {
      const s = commonSample.byMethod[method][stat];
      console.log(`    ${method.padEnd(16)} ${String(s.n).padStart(4)} ${f(s.mae).padStart(8)} ${f(s.medianAe).padStart(7)} ${f(s.bias).padStart(7)}`);
    }
  }
  for (const segment of ["minutesBucket", "usageBucket"] as const) {
    console.log(`\n  By ${segment} (MAE for minutes / pts)`);
    for (const [bucket, summary] of Object.entries(report.pooled.conditional.segments[segment])) {
      const cells = (["previous_game", "last_10", "jkb_baseline_v0", "jkb_minutes_v1"] as const).map((m) => `${m}=${f(summary.byMethod[m].minutes.mae, 2)}/${f(summary.byMethod[m].pts.mae, 2)}`);
      console.log(`    ${bucket.padEnd(9)} n=${String(summary.n).padStart(4)}  ${cells.join("  ")}`);
    }
  }
}

function printAvailability(report: EvaluationReport): void {
  const a = report.pooled.availability;
  console.log(`\nAvailability (universe n=${a.universe}; excluded unestablished=${a.excluded.unestablished}, played outside universe=${a.excluded.playedOutsideUniverse}; no pregame status=${a.withoutPregameStatus})`);
  console.log("    model            Brier   logLoss   acc   observed");
  for (const [model, s] of Object.entries(a.byModel)) console.log(`    ${model.padEnd(15)} ${f(s.brier, 4).padStart(7)} ${f(s.logLoss, 4).padStart(8)} ${f(s.accuracy, 3).padStart(6)} ${f(s.observedRate, 3).padStart(8)}`);
  console.log("  Observed play rate by pregame status: " + Object.entries(a.byStatus).map(([k, v]) => `${k}=${f(v.observedRate, 2)} (n=${v.n})`).join(", "));
  console.log(`  Unconditional minutes MAE: conditional-only=${f(a.unconditionalMinutes.conditionalOnly.mae)}, availability-weighted=${f(a.unconditionalMinutes.availabilityWeighted.mae)}`);
}

function main(): void {
  const seed = Number(arg("seed", String(DEFAULT_EVALUATION_LEAGUE.seed)));
  if (!Number.isSafeInteger(seed)) throw new Error("--seed must be an integer");
  const dataset = generateEvaluationLeague({ ...DEFAULT_EVALUATION_LEAGUE, seed });
  const folds = [...seasonFolds("s1", "2060-10-20", "2061-01-06"), ...seasonFolds("s2", "2061-10-20", "2062-01-06")];
  const report = runEvaluation({
    dataset,
    license: SOURCE_LICENSES.synthetic,
    config: { cutoffPolicy: { leadMinutes: 90, resultLagMinutes: 180 }, folds, baselineParams: BASELINE_V0_PUBLIC_PARAMS, minutesV1Params: DEFAULT_MINUTES_V1_PARAMS },
  });
  const m = report.manifest;
  console.log(`Manifest ${m.manifestId.slice(0, 12)} | evidence=${m.evidenceClass} | fixture=${(m.dataset.provenance as { fixtureVersion?: string }).fixtureVersion} seed=${seed}`);
  console.log(`Cutoff: tipoff - ${m.featureCutoff.policy.leadMinutes} min (results usable ${m.featureCutoff.policy.resultLagMinutes} min after tipoff) | first ${m.featureCutoff.first} | last ${m.featureCutoff.last}`);
  console.log(`Windows: ${m.windows.length} rolling folds; results sha256 ${m.resultsSha256.slice(0, 12)}`);
  console.log(`Diagnostics: ${JSON.stringify(report.diagnostics)}`);
  printConditional(report);
  printAvailability(report);
  console.log("\nAcceptance criteria");
  for (const o of m.acceptance.outcomes) console.log(`  ${o.passed ? "PASS" : "FAIL"}  ${o.id.padEnd(26)} observed=${f(o.observed, 3)} threshold=${f(o.threshold, 3)}  (${o.detail})`);
  console.log(`\nOverall: ${m.acceptance.passed ? "PASS" : "FAIL"} on synthetic data (mechanism check only)`);
  const out = arg("out", "");
  if (out) writeFileSync(out, `${JSON.stringify(report, null, 2)}\n`);
}

main();
